using Xunit;

public class PricingAcceptanceTests
{
    // Young rider gets a motorcycle quote
    [Fact(Skip = "later")]
    public void Young_rider_gets_a_motorcycle_quote()
    {
        var result = new RequestQuote(new InMemoryQuotes()).Handle(new QuoteRequest(Age: 25, Vehicle: "motorcycle"));
        Assert.Equal(480.50m, result.Premium);
    }
}
